{
    return min(15u, (uint)max(0., floor(log(max(z, Near) / Near) / log(Far / Near) * 16)));
}
uint cellID(float2 pixel, float z)
{
    uint2 t = min(uint2(pixel / aa[0].xy * float2(16, 9)), uint2(15, 8));
    return t.y * 16 + t.x + (aa[0].z > 2.5 ? slice(z) * 144 : 0);
