    // Stable ascending IDs preserve floating-point light summation across all paths.
    // Parallel intersection tests are followed by a bounded 256-entry compaction.
    if (lane == 0)
    {
        uint   count  = 0;
        float4 packed = 0;
        for (uint id = 0; id < (uint)aa[1].x; id++)
